NTTSX024.ol:
#Determine which LGA would be selected by the LGA Selection Function based on the SSEA Profile
#
# Initialise
VAR_lgaSelect := "LGA_A";
#
if (NCFT1BW0 == "LGA_A") lor (NCFT1BW0 == "LGA_B") then
    VAR_lgaSelect := NCFT1BW0;
else
    VAR_lgaSelect := NCFT1BX0;
endif;
#
#SSCE_LGA_A_THR = (7.8539816E-1)
if (NCAT6RU0 <= 7.8539816E-1) then
    VAR_lgaSelect := "LGA_A";
endif;
#
#SSCE_LGA_B_THR = (2.00712864E0)
if (NCAT6RU0 >= 2.00712864E0) then
    VAR_lgaSelect := "LGA_B";
endif;
#
return(VAR_lgaSelect);
